sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var desc = (current.description || '').toLowerCase();
    var cat = (current.category || current.complaint_category || '').toLowerCase();

    // Check for critical keywords or food safety
    var criticalWords = ['sick', 'poison', 'hospital', 'expired', 'hazard', 'sue', 'lawyer', 'foreign object'];
    var hasCritical = criticalWords.some(function(w) { return desc.indexOf(w) !== -1; });

    // Repeat incident check (>= 2 complaints in last 30 days from same opener)
    var isRepeat = false;
    if (current.opened_by) {
        var hist = new GlideRecord('x_1958581_retail_0_retail_complaint');
        hist.addQuery('opened_by', current.opened_by);
        hist.addQuery('sys_created_on', '>=', gs.daysAgo(30));
        hist.query();
        if (hist.getRowCount() >= 2) {
            isRepeat = true;
        }
    }

    // Set the boolean field on the record
    if (current.isValidField('repeat_customer')) {
        current.repeat_customer = isRepeat;
    } else if (current.isValidField('u_repeat_customer')) {
        current.u_repeat_customer = isRepeat;
    } else if (current.isValidField('is_repeat_customer')) {
        current.is_repeat_customer = isRepeat;
    }

    if (cat === 'food_safety' || hasCritical) {
        current.business_risk = 'critical';
        current.customer_sentiment = 'highly_dissatisfied';
        current.priority = 1;
    } else if (isRepeat) {
        current.business_risk = 'high';
        current.customer_sentiment = 'dissatisfied';
        current.priority = 2;
    } else {
        current.business_risk = 'low';
        current.customer_sentiment = 'neutral';
        current.priority = 4;
    }
})(current, previous);
